import {useState} from "react";
import type {Product,SortOption,Cart} from "./model";
import {SORT_OPTIONS} from "./model";
import {visibleProducts,categoriesOf,addToCart,cartCount,isSortOption} from "./logic";
import {paginate} from "./pagination";
import {ProductCard} from "./ProductCard";
import styles from "./Catalog.module.css";
export function Catalog({products}:{products:readonly Product[]}){const [query,setQuery]=useState("");const [category,setCategory]=useState("ALL");const [onlyInStock,setOnlyInStock]=useState(false);const [sort,setSort]=useState<SortOption>("price-asc");const [page,setPage]=useState(1);const [cart,setCart]=useState<Cart>({});const categories=categoriesOf(products);const visible=visibleProducts(products,{query,category,onlyInStock},sort);const result=paginate(visible,page,12);const count=cartCount(cart);function resetFilters(){setQuery("");setCategory("ALL");setOnlyInStock(false);setPage(1);}function handleAdd(id:number){const product=products.find(item=>item.id===id);if(product?.inStock)setCart(previous=>addToCart(previous,product));}return <main className={styles.catalog}><header><h1>Katalog</h1><p aria-live="polite">Koszyk: {count} szt.</p></header><section className={styles.filters} aria-label="Filtry produktów"><label>Szukaj po nazwie lub marce<input type="search" value={query} onChange={event=>{setQuery(event.currentTarget.value);setPage(1);}}/></label><label>Kategoria<select value={category} onChange={event=>{setCategory(event.currentTarget.value);setPage(1);}}><option value="ALL">Wszystkie</option>{categories.map(value=><option key={value} value={value}>{value}</option>)}</select></label><label><input type="checkbox" checked={onlyInStock} onChange={event=>{setOnlyInStock(event.currentTarget.checked);setPage(1);}}/>Tylko dostępne</label><label>Sortowanie<select value={sort} onChange={event=>{const next=event.currentTarget.value;if(isSortOption(next)){setSort(next);setPage(1);}}}>{SORT_OPTIONS.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select></label></section><p aria-live="polite">{visible.length===0?"Brak wyników":`Produkty ${result.from}–${result.to} z ${visible.length}`}</p>{visible.length===0?<section><p>Brak produktów spełniających kryteria</p><button type="button" onClick={resetFilters}>Wyczyść filtry</button></section>:<div className={styles.grid}>{result.pageItems.map(product=><ProductCard key={product.id} product={product} onAdd={handleAdd}/>)}</div>}<nav aria-label="Strony katalogu"><button type="button" disabled={result.currentPage===1} onClick={()=>setPage(result.currentPage-1)}>Poprzednia</button><span>Strona {result.currentPage} z {result.pageCount}</span><button type="button" disabled={result.currentPage===result.pageCount} onClick={()=>setPage(result.currentPage+1)}>Następna</button></nav></main>;}

