export type Product=Readonly<{id:number;name:string;brand:string;category:string;priceGrosze:number;rating:number;inStock:boolean}>;
export const SORT_OPTIONS=[{value:"price-asc",label:"Cena rosnąco"},{value:"price-desc",label:"Cena malejąco"},{value:"name",label:"Nazwa A–Z"},{value:"rating",label:"Ocena malejąco"}] as const;
export type SortOption=(typeof SORT_OPTIONS)[number]["value"];
export type Filters=Readonly<{query:string;category:string;onlyInStock:boolean}>;
export type Cart=Readonly<Partial<Record<number,number>>>;
const COMPARE:Record<SortOption,(a:Product,b:Product)=>number>={"price-asc":(a,b)=>a.priceGrosze-b.priceGrosze,"price-desc":(a,b)=>b.priceGrosze-a.priceGrosze,name:(a,b)=>a.name.localeCompare(b.name,"pl"),rating:(a,b)=>b.rating-a.rating};
export function visibleProducts(products:readonly Product[],filters:Filters,sort:SortOption):Product[]{const q=filters.query.trim().toLowerCase();return products.filter(product=>(filters.category==="ALL"||product.category===filters.category)&&(!filters.onlyInStock||product.inStock)&&(q===""||product.name.toLowerCase().includes(q)||product.brand.toLowerCase().includes(q))).toSorted(COMPARE[sort]);}
